 20 | // Login handles POST /api/auth/login.
 21 | //
 22 | //	challenge returned -> email OTP sent, complete it with /api/auth/2fa/verify
 23 | //	tokens returned    -> 2FA not required for this account
 24 | func (h *AuthHandler) Login(w http.ResponseWriter, r *http.Request) {
 25 | 	var body loginRequest
 26 | 	if err := decodeJSON(w, r, &body); err != nil {
 27 | 		writeErr(w, r, err)
 28 | 		return
 29 | 	}
 30 | 	if _, err := requiredString(body.Identifier, "identifier"); err != nil {
 31 | 		writeErr(w, r, err)
 32 | 		return
 33 | 	}
 34 | 	if body.Password == "" {
 35 | 		writeErr(w, r, requiredFieldError("password"))
 36 | 		return
 37 | 	}
 38 | 
 39 | 	result, err := h.svc.Login(r.Context(), service.LoginInput{
 40 | 		Identifier: body.Identifier,
 41 | 		Password:   body.Password,
 42 | 	}, requestMeta(r))
 43 | 	if err != nil {
 44 | 		writeErr(w, r, err)
 45 | 		return
 46 | 	}
 47 | 	writeJSON(w, http.StatusOK, result)
 48 | }
