 1 | // Package middleware holds the cross-cutting HTTP concerns: bearer-token
 2 | // authentication, CORS for the admin panel, request logging and cache headers.
 3 | package middleware
 4 | 
 5 | import (
 6 | 	"context"
 7 | 	"net/http"
 8 | 	"strings"
 9 | 
10 | 	"github.com/coderkamlesh/portfolio_api/internal/apierr"
11 | 	"github.com/coderkamlesh/portfolio_api/internal/security"
12 | )
13 | 
14 | type contextKey string
15 | 
16 | const claimsContextKey contextKey = "auth.access_claims"
17 | 
18 | // RequireAuth validates the `Authorization: Bearer <jwt>` header and stores the
19 | // access-token claims in the request context.
20 | func RequireAuth(tokens *security.TokenManager) func(http.Handler) http.Handler {
21 | 	return func(next http.Handler) http.Handler {
22 | 		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
23 | 			raw := bearerToken(r)
24 | 			if raw == "" {
25 | 				writeAuthError(w, apierr.Unauthorized("missing_token", "Authorization header with a bearer token is required."))
26 | 				return
27 | 			}
28 | 
29 | 			claims, err := tokens.ParseAccessToken(raw)
30 | 			if err != nil {
31 | 				writeAuthError(w, apierr.Wrap(err, http.StatusUnauthorized, "invalid_token",
32 | 					"Your session is invalid or has expired. Please sign in again."))
33 | 				return
34 | 			}
35 | 
36 | 			ctx := context.WithValue(r.Context(), claimsContextKey, claims)
37 | 			next.ServeHTTP(w, r.WithContext(ctx))
38 | 		})
39 | 	}
40 | }
41 | 
42 | // ClaimsFromContext returns the validated access claims of the current request.
43 | func ClaimsFromContext(ctx context.Context) (*security.AccessClaims, bool) {
44 | 	claims, ok := ctx.Value(claimsContextKey).(*security.AccessClaims)
45 | 	return claims, ok
46 | }
47 | 
48 | // AdminIDFromContext returns the subject (admin_users.id) of the current token.
49 | func AdminIDFromContext(ctx context.Context) (string, bool) {
50 | 	claims, ok := ClaimsFromContext(ctx)
51 | 	if !ok || claims.Subject == "" {
52 | 		return "", false
53 | 	}
54 | 	return claims.Subject, true
55 | }
56 | 
57 | func bearerToken(r *http.Request) string {
58 | 	header := r.Header.Get("Authorization")
59 | 	if header == "" {
60 | 		return ""
61 | 	}
62 | 	parts := strings.SplitN(header, " ", 2)
63 | 	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
64 | 		return ""
65 | 	}
66 | 	return strings.TrimSpace(parts[1])
67 | }
68 | 
69 | // writeAuthError renders the shared JSON error envelope without importing the
70 | // handler package (which would create a cycle).
71 | func writeAuthError(w http.ResponseWriter, err error) {
72 | 	apiErr := apierr.From(err)
73 | 	w.Header().Set("Content-Type", "application/json; charset=utf-8")
74 | 	w.Header().Set("Cache-Control", "no-store")
75 | 	if apiErr.Status == http.StatusUnauthorized {
76 | 		w.Header().Set("WWW-Authenticate", `Bearer realm="portfolio-api"`)
77 | 	}
78 | 	w.WriteHeader(apiErr.Status)
79 | 	_, _ = w.Write([]byte(`{"error":{"code":"` + apiErr.Code + `","message":` + quote(apiErr.Message) + `}}`))
80 | }
81 | 
82 | func quote(v string) string {
83 | 	replacer := strings.NewReplacer(`\`, `\\`, `"`, `\"`)
84 | 	return `"` + replacer.Replace(v) + `"`
85 | }

 1 | package middleware
 2 | 
 3 | import (
 4 | 	"log"
 5 | 	"net/http"
 6 | 	"strings"
 7 | 	"time"
 8 | )
 9 | 
10 | // NoStore prevents browsers and proxies from caching authenticated responses.
11 | func NoStore(next http.Handler) http.Handler {
12 | 	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
13 | 		w.Header().Set("Cache-Control", "no-store")
14 | 		w.Header().Set("Pragma", "no-cache")
15 | 		next.ServeHTTP(w, r)
16 | 	})
17 | }
18 | 
19 | // CORS allows the admin panel (a different origin) to call the API with the
20 | // Authorization header. Only origins from AUTH_ALLOWED_ORIGINS are accepted;
21 | // a wildcard entry ("*") allows any origin.
22 | func CORS(allowedOrigins []string) func(http.Handler) http.Handler {
23 | 	allowed := make(map[string]struct{}, len(allowedOrigins))
24 | 	wildcard := false
25 | 	for _, origin := range allowedOrigins {
26 | 		if origin == "*" {
27 | 			wildcard = true
28 | 			continue
29 | 		}
30 | 		allowed[strings.ToLower(strings.TrimSpace(origin))] = struct{}{}
31 | 	}
32 | 
33 | 	return func(next http.Handler) http.Handler {
34 | 		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
35 | 			origin := r.Header.Get("Origin")
36 | 			if origin != "" && allowedOrigin(origin, allowed, wildcard) {
37 | 				w.Header().Set("Access-Control-Allow-Origin", origin)
38 | 				w.Header().Add("Vary", "Origin")
39 | 				if !wildcard {
40 | 					// Credentials cannot be combined with a wildcard origin.
41 | 					w.Header().Set("Access-Control-Allow-Credentials", "true")
42 | 				}
43 | 			}
44 | 
45 | 			if r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != "" {
46 | 				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
47 | 				w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, X-Requested-With")
48 | 				w.Header().Set("Access-Control-Max-Age", "600")
49 | 				w.WriteHeader(http.StatusNoContent)
50 | 				return
51 | 			}
52 | 
53 | 			next.ServeHTTP(w, r)
54 | 		})
55 | 	}
56 | }
57 | 
58 | func allowedOrigin(origin string, allowed map[string]struct{}, wildcard bool) bool {
59 | 	if wildcard {
60 | 		return true
61 | 	}
62 | 	_, ok := allowed[strings.ToLower(origin)]
63 | 	return ok
64 | }
65 | 
66 | // Logger writes one line per request with status, size and duration.
67 | func Logger(next http.Handler) http.Handler {
68 | 	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
69 | 		started := time.Now()
70 | 		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
71 | 		next.ServeHTTP(rec, r)
72 | 		log.Printf("%s %s -> %d %dB in %s", r.Method, r.URL.Path, rec.status, rec.written,
73 | 			time.Since(started).Round(time.Millisecond))
74 | 	})
75 | }
76 | 
77 | type statusRecorder struct {
78 | 	http.ResponseWriter
79 | 	status  int
80 | 	written int
81 | }
82 | 
83 | func (r *statusRecorder) WriteHeader(status int) {
84 | 	r.status = status
85 | 	r.ResponseWriter.WriteHeader(status)
86 | }
87 | 
88 | func (r *statusRecorder) Write(b []byte) (int, error) {
89 | 	n, err := r.ResponseWriter.Write(b)
90 | 	r.written += n
91 | 	return n, err
92 | }

 1 | // Package apierr defines the single error type the service layer returns and
 2 | // the HTTP layer understands. Using one type keeps the mapping from business
 3 | // failure to status code + machine-readable code in exactly one place.
 4 | package apierr
 5 | 
 6 | import (
 7 | 	"errors"
 8 | 	"fmt"
 9 | 	"net/http"
10 | )
11 | 
12 | // Error is an API-visible error: an HTTP status, a stable machine-readable
13 | // code the frontend can switch on, and a human message.
14 | type Error struct {
15 | 	Status  int
16 | 	Code    string
17 | 	Message string
18 | 	Err     error
19 | 	// RetryAfter (seconds) is emitted as the Retry-After header when > 0.
20 | 	RetryAfter int
21 | }
22 | 
23 | func (e *Error) Error() string {
24 | 	if e.Err != nil {
25 | 		return fmt.Sprintf("%s: %s: %v", e.Code, e.Message, e.Err)
26 | 	}
27 | 	return fmt.Sprintf("%s: %s", e.Code, e.Message)
28 | }
29 | 
30 | func (e *Error) Unwrap() error { return e.Err }
31 | 
32 | // New builds an error without an underlying cause.
33 | func New(status int, code, message string) *Error {
34 | 	return &Error{Status: status, Code: code, Message: message}
35 | }
36 | 
37 | // Wrap builds an error that keeps the cause for logs while exposing only the
38 | // curated message to clients.
39 | func Wrap(err error, status int, code, message string) *Error {
40 | 	return &Error{Status: status, Code: code, Message: message, Err: err}
41 | }
42 | 
43 | // From extracts the API error from err, or returns nil when err is nil.
44 | // Non-API errors become a generic 500 so internal details never leak.
45 | func From(err error) *Error {
46 | 	if err == nil {
47 | 		return nil
48 | 	}
49 | 	var apiErr *Error
50 | 	if errors.As(err, &apiErr) {
51 | 		return apiErr
52 | 	}
53 | 	return Wrap(err, http.StatusInternalServerError, "internal_error", "Something went wrong. Please try again.")
54 | }
55 | 
56 | // BadRequest is a helper for handler-level payload validation.
57 | func BadRequest(code, message string) *Error {
58 | 	return New(http.StatusBadRequest, code, message)
59 | }
60 | 
61 | // Unauthorized is a helper for missing/invalid credentials.
62 | func Unauthorized(code, message string) *Error {
63 | 	return New(http.StatusUnauthorized, code, message)
64 | }

  1 | package service
  2 | 
  3 | import (
  4 | 	"context"
  5 | 	"errors"
  6 | 	"log"
  7 | 
  8 | 	"github.com/coderkamlesh/portfolio_api/internal/models"
  9 | 	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
 10 | 	"github.com/coderkamlesh/portfolio_api/internal/security"
 11 | )
 12 | 
 13 | // issueSession mints an access token plus a rotating opaque refresh token.
 14 | // Only the SHA-256 hash of the refresh token is persisted.
 15 | func (s *AuthService) issueSession(ctx context.Context, admin *models.AdminUser, meta RequestMeta) (*TokenPair, error) {
 16 | 	accessToken, accessExpiresAt, err := s.tokens.IssueAccessToken(admin)
 17 | 	if err != nil {
 18 | 		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
 19 | 	}
 20 | 
 21 | 	refreshToken, err := security.GenerateRefreshToken()
 22 | 	if err != nil {
 23 | 		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
 24 | 	}
 25 | 
 26 | 	now := s.now()
 27 | 	refreshExpiresAt := now.Add(s.cfg.RefreshTokenTTL)
 28 | 	record := &models.RefreshToken{
 29 | 		ID:        ids.New(),
 30 | 		AdminID:   admin.ID,
 31 | 		TokenHash: security.HashToken(refreshToken),
 32 | 		ExpiresAt: refreshExpiresAt,
 33 | 		UserAgent: sanitizeUserAgent(meta.UserAgent),
 34 | 		IPAddress: meta.IPAddress,
 35 | 		CreatedAt: now,
 36 | 	}
 37 | 	if err := s.refresh.Create(ctx, record); err != nil {
 38 | 		return nil, err
 39 | 	}
 40 | 
 41 | 	return &TokenPair{
 42 | 		TokenType:        "Bearer",
 43 | 		AccessToken:      accessToken,
 44 | 		ExpiresIn:        int(s.tokens.AccessTTL().Seconds()),
 45 | 		ExpiresAt:        accessExpiresAt,
 46 | 		RefreshToken:     refreshToken,
 47 | 		RefreshExpiresIn: int(s.cfg.RefreshTokenTTL.Seconds()),
 48 | 		RefreshExpiresAt: refreshExpiresAt,
 49 | 	}, nil
 50 | }
 51 | 
 52 | // Refresh rotates a refresh token: the presented token is revoked and a fresh
 53 | // pair is issued. Replaying an already-revoked token revokes every session of
 54 | // that admin, which is the standard protection against a stolen token.
 55 | func (s *AuthService) Refresh(ctx context.Context, in RefreshInput, meta RequestMeta) (*LoginResult, error) {
 56 | 	if in.RefreshToken == "" {
 57 | 		return nil, errInvalidRefreshToken()
 58 | 	}
 59 | 
 60 | 	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
 61 | 	if err != nil {
 62 | 		if errors.Is(err, models.ErrNotFound) {
 63 | 			return nil, errInvalidRefreshToken()
 64 | 		}
 65 | 		return nil, err
 66 | 	}
 67 | 
 68 | 	now := s.now()
 69 | 
 70 | 	if record.RevokedAt != nil {
 71 | 		s.revokeAllSessions(ctx, record.AdminID, "refresh_token_reuse")
 72 | 		return nil, errRefreshTokenReused()
 73 | 	}
 74 | 	if !now.Before(record.ExpiresAt) {
 75 | 		if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
 76 | 			log.Printf("⚠️  auth: could not revoke expired token %s: %v", record.ID, err)
 77 | 		}
 78 | 		return nil, errInvalidRefreshToken()
 79 | 	}
 80 | 
 81 | 	admin, err := s.adminFor(ctx, record.AdminID)
 82 | 	if err != nil {
 83 | 		return nil, err
 84 | 	}
 85 | 	if !admin.IsActive {
 86 | 		s.revokeAllSessions(ctx, admin.ID, "account_disabled")
 87 | 		return nil, errAccountDisabled()
 88 | 	}
 89 | 
 90 | 	rotated, err := s.refresh.Revoke(ctx, record.ID, now)
 91 | 	if err != nil {
 92 | 		return nil, err
 93 | 	}
 94 | 	if !rotated {
 95 | 		// Someone else rotated it a moment ago — treat as reuse.
 96 | 		s.revokeAllSessions(ctx, admin.ID, "refresh_token_race")
 97 | 		return nil, errRefreshTokenReused()
 98 | 	}
 99 | 
100 | 	tokens, err := s.issueSession(ctx, admin, meta)
101 | 	if err != nil {
102 | 		return nil, err
103 | 	}
104 | 	s.auditEvent(ctx, admin.ID, models.AuditTokenRefreshed, "", nil)
105 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
106 | }
107 | 
108 | // Logout revokes one session, or every session of the admin.
109 | func (s *AuthService) Logout(ctx context.Context, adminID string, in LogoutInput) error {
110 | 	now := s.now()
111 | 
112 | 	if in.AllDevices || in.RefreshToken == "" {
113 | 		if _, err := s.refresh.RevokeAllForAdmin(ctx, adminID, now); err != nil {
114 | 			return err
115 | 		}
116 | 		s.auditEvent(ctx, adminID, models.AuditLoggedOut, "all_devices", nil)
117 | 		return nil
118 | 	}
119 | 
120 | 	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
121 | 	if err != nil {
122 | 		if errors.Is(err, models.ErrNotFound) {
123 | 			return nil // already gone — logging out is idempotent
124 | 		}
125 | 		return err
126 | 	}
127 | 	if record.AdminID != adminID {
128 | 		return errInvalidRefreshToken()
129 | 	}
130 | 	if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
131 | 		return err
132 | 	}
133 | 	s.auditEvent(ctx, adminID, models.AuditLoggedOut, "single_device", nil)
134 | 	return nil
135 | }
