 11 | // fakeOTPStore is an in-memory otp_challenges table. It is mutex-protected
 12 | // because the service prunes expired rows from a detached goroutine.
 13 | type fakeOTPStore struct {
 14 | 	mu   sync.Mutex
 15 | 	rows []*models.OTPChallenge
 16 | }
 17 | 
 18 | func (f *fakeOTPStore) Create(_ context.Context, c *models.OTPChallenge) error {
 19 | 	f.mu.Lock()
 20 | 	defer f.mu.Unlock()
 21 | 	f.rows = append(f.rows, c)
 22 | 	return nil
 23 | }
 24 | 
 25 | func (f *fakeOTPStore) FindByID(_ context.Context, id string) (*models.OTPChallenge, error) {
 26 | 	f.mu.Lock()
 27 | 	defer f.mu.Unlock()
 28 | 	for _, r := range f.rows {
 29 | 		if r.ID == id {
 30 | 			return r, nil
 31 | 		}
 32 | 	}
 33 | 	return nil, models.ErrNotFound
 34 | }
 35 | 
 36 | func (f *fakeOTPStore) FindLatestPending(_ context.Context, adminID, purpose string, at time.Time) (*models.OTPChallenge, error) {
 37 | 	f.mu.Lock()
 38 | 	defer f.mu.Unlock()
 39 | 
 40 | 	var latest *models.OTPChallenge
 41 | 	for _, r := range f.rows {
 42 | 		if r.AdminID != adminID || r.Purpose != purpose || r.ConsumedAt != nil || !at.Before(r.ExpiresAt) {
 43 | 			continue
 44 | 		}
 45 | 		if latest == nil || r.CreatedAt.After(latest.CreatedAt) {
 46 | 			latest = r
 47 | 		}
 48 | 	}
 49 | 	if latest == nil {
 50 | 		return nil, models.ErrNotFound
 51 | 	}
 52 | 	return latest, nil
 53 | }
 54 | 
 55 | func (f *fakeOTPStore) CountCreatedSince(_ context.Context, adminID, purpose string, since time.Time) (int, error) {
 56 | 	f.mu.Lock()
 57 | 	defer f.mu.Unlock()
 58 | 
 59 | 	count := 0
 60 | 	for _, r := range f.rows {
 61 | 		if r.AdminID == adminID && r.Purpose == purpose && !r.CreatedAt.Before(since) {
 62 | 			count++
 63 | 		}
 64 | 	}
 65 | 	return count, nil
 66 | }
 67 | 
 68 | func (f *fakeOTPStore) InvalidatePending(_ context.Context, adminID, purpose string, at time.Time) error {
 69 | 	f.mu.Lock()
 70 | 	defer f.mu.Unlock()
 71 | 	for _, r := range f.rows {
 72 | 		if r.AdminID == adminID && r.Purpose == purpose && r.ConsumedAt == nil {
 73 | 			consumed := at
 74 | 			r.ConsumedAt = &consumed
 75 | 		}
 76 | 	}
 77 | 	return nil
 78 | }
 79 | 
 80 | func (f *fakeOTPStore) IncrementAttempts(_ context.Context, id string) (int, error) {
 81 | 	f.mu.Lock()
 82 | 	defer f.mu.Unlock()
 83 | 	for _, r := range f.rows {
 84 | 		if r.ID == id {
 85 | 			r.AttemptCount++
 86 | 			return r.AttemptCount, nil
 87 | 		}
 88 | 	}
 89 | 	return 0, models.ErrNotFound
 90 | }
 91 | 
 92 | func (f *fakeOTPStore) Consume(_ context.Context, id string, at time.Time) (bool, error) {
 93 | 	f.mu.Lock()
 94 | 	defer f.mu.Unlock()
 95 | 	for _, r := range f.rows {
 96 | 		if r.ID == id {
 97 | 			if r.ConsumedAt != nil {
 98 | 				return false, nil
 99 | 			}
100 | 			consumed := at
101 | 			r.ConsumedAt = &consumed
102 | 			return true, nil
103 | 		}
104 | 	}
105 | 	return false, nil
106 | }
