 15 | // ChangePassword rotates the password of the signed-in admin. Every other
 16 | // session is revoked and a fresh pair is returned so the caller stays signed
 17 | // in on the current device.
 18 | func (s *AuthService) ChangePassword(ctx context.Context, adminID string, in ChangePasswordInput, meta RequestMeta) (*TokenPair, error) {
 19 | 	if err := s.validatePassword(in.NewPassword); err != nil {
 20 | 		return nil, err
 21 | 	}
 22 | 
 23 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.CurrentPassword)
 24 | 	if err != nil {
 25 | 		return nil, err
 26 | 	}
 27 | 
 28 | 	same, err := security.VerifyPassword(admin.PasswordHash, in.NewPassword)
 29 | 	if err != nil {
 30 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
 31 | 	}
 32 | 	if same {
 33 | 		return nil, errSamePassword()
 34 | 	}
 35 | 
 36 | 	hash, err := security.HashPassword(in.NewPassword)
 37 | 	if err != nil {
 38 | 		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
 39 | 	}
 40 | 	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
 41 | 		return nil, err
 42 | 	}
 43 | 
 44 | 	// Kill every existing session, then start a new one for this device.
 45 | 	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
 46 | 		log.Printf("⚠️  auth: could not revoke sessions after password change: %v", err)
 47 | 	}
 48 | 	tokens, err := s.issueSession(ctx, admin, meta)
 49 | 	if err != nil {
