 57 | // ForgotPassword mails a reset code and returns a client-facing challenge.
 58 | // Unknown and inactive addresses receive a non-persisted challenge with the same
 59 | // response shape so this endpoint cannot be used to enumerate admin accounts.
 60 | func (s *AuthService) ForgotPassword(ctx context.Context, in ForgotPasswordInput, meta RequestMeta) (*ChallengeView, error) {
 61 | 	emailAddress := strings.ToLower(strings.TrimSpace(in.Email))
 62 | 	if emailAddress == "" {
 63 | 		return s.syntheticResetChallenge(emailAddress), nil
 64 | 	}
 65 | 
 66 | 	admin, err := s.admins.FindByIdentifier(ctx, emailAddress)
 67 | 	if err != nil {
 68 | 		if errors.Is(err, models.ErrNotFound) {
 69 | 			log.Printf("🔐 auth: password reset requested for unknown address %s", emailAddress)
 70 | 			return s.syntheticResetChallenge(emailAddress), nil
 71 | 		}
 72 | 		return nil, err
 73 | 	}
 74 | 	if !admin.IsActive {
 75 | 		return s.syntheticResetChallenge(emailAddress), nil
 76 | 	}
 77 | 
 78 | 	challenge, err := s.issueOTP(ctx, admin, models.OTPPurposePasswordReset, meta)
 79 | 	if err != nil {
 80 | 		var apiErr *apierr.Error
 81 | 		if errors.As(err, &apiErr) &&
 82 | 			apiErr.Code != CodeOTPTooMany &&
 83 | 			apiErr.Code != CodeEmailDeliveryFailed {
 84 | 			return nil, err
 85 | 		}
 86 | 		// Rate limiting and mail failures use the same generic response as an
 87 | 		// unknown account so the endpoint cannot reveal whether email exists.
 88 | 		log.Printf("⚠️  auth: reset request not completed for admin %s: %v", admin.ID, err)
 89 | 		return s.syntheticResetChallenge(emailAddress), nil
 90 | 	}
 91 | 	s.auditEvent(ctx, admin.ID, models.AuditPasswordResetAsked, "", nil)
 92 | 	return challenge, nil
 93 | }
