100 | 		Email:        security.MaskEmail(emailAddress),
101 | 		CodeLength:   s.cfg.OTPLength,
102 | 		ExpiresAt:    now.Add(s.cfg.OTPTTL),
103 | 		ExpiresIn:    int(s.cfg.OTPTTL.Seconds()),
104 | 		AttemptsLeft: s.cfg.OTPMaxAttempts,
105 | 		ResendAfter:  int(s.cfg.OTPResendCooldown.Seconds()),
106 | 	}
