110 | func (s *AuthService) ResetPassword(ctx context.Context, in ResetPasswordInput, meta RequestMeta) (*LoginResult, error) {
111 | 	if err := s.validatePassword(in.NewPassword); err != nil {
112 | 		return nil, err
113 | 	}
114 | 
115 | 	challenge, err := s.loadChallenge(ctx, in.ChallengeID, models.OTPPurposePasswordReset)
116 | 	if err != nil {
117 | 		return nil, err
118 | 	}
119 | 
120 | 	admin, err := s.checkOTP(ctx, challenge, in.OTP)
121 | 	if err != nil {
122 | 		return nil, err
123 | 	}
124 | 
125 | 	hash, err := security.HashPassword(in.NewPassword)
126 | 	if err != nil {
127 | 		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
128 | 	}
129 | 	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
130 | 		return nil, err
131 | 	}
132 | 	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
133 | 		log.Printf("⚠️  auth: could not revoke sessions after password reset: %v", err)
134 | 	}
135 | 	if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
136 | 		log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
137 | 	}
138 | 
139 | 	tokens, err := s.issueSession(ctx, admin, meta)
140 | 	if err != nil {
141 | 		return nil, err
142 | 	}
143 | 	s.auditEvent(ctx, admin.ID, models.AuditPasswordReset, "", nil)
144 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
145 | }
