130 | func scanAdmin(row rowScanner) (*models.AdminUser, error) {
131 | 	var (
132 | 		a         models.AdminUser
133 | 		active    sql.NullInt64
134 | 		lastLogin sql.NullString
135 | 		createdAt string
136 | 		updatedAt string
137 | 	)
138 | 	if err := row.Scan(&a.ID, &a.Username, &a.Email, &a.PasswordHash, &active, &lastLogin, &createdAt, &updatedAt); err != nil {
139 | 		if errors.Is(err, sql.ErrNoRows) {
140 | 			return nil, models.ErrNotFound
141 | 		}
142 | 		return nil, fmt.Errorf("admin: scan: %w", err)
143 | 	}
144 | 	a.IsActive = boolFromInt(active)
145 | 
146 | 	lastLoginAt, err := database.ParseTimePtr(lastLogin)
147 | 	if err != nil {
148 | 		return nil, fmt.Errorf("admin: parse last_login_at: %w", err)
149 | 	}
150 | 	a.LastLoginAt = lastLoginAt
151 | 
152 | 	if a.CreatedAt, err = database.ParseTime(createdAt); err != nil {
153 | 		return nil, fmt.Errorf("admin: parse created_at: %w", err)
154 | 	}
155 | 	if a.UpdatedAt, err = database.ParseTime(updatedAt); err != nil {
156 | 		return nil, fmt.Errorf("admin: parse updated_at: %w", err)
157 | 	}
158 | 	return &a, nil
159 | }
