 62 | // Load reads .env (when present) plus the process environment and validates
 63 | // the result. It exits the process on an unusable configuration so that a
 64 | // misconfigured container fails loudly instead of serving broken traffic.
 65 | func Load() *Config {
 66 | 	if err := godotenv.Load(); err != nil {
 67 | 		log.Println("No .env file found, using environment variables")
 68 | 	}
 69 | 
 70 | 	cfg := &Config{
 71 | 		// PORT is set by the Lambda Web Adapter; SERVER_PORT wins locally.
 72 | 		ServerPort:     getEnv("SERVER_PORT", getEnv("PORT", "8080")),
 73 | 		AllowedOrigins: getEnvCSV("AUTH_ALLOWED_ORIGINS", []string{"http://localhost:5173", "http://localhost:3000"}),
 74 | 
 75 | 		TursoURL:   os.Getenv("TURSO_DATABASE_URL"),
 76 | 		TursoToken: os.Getenv("TURSO_AUTH_TOKEN"),
 77 | 
 78 | 		JWTSecret:       os.Getenv("JWT_SECRET"),
 79 | 		JWTIssuer:       getEnv("JWT_ISSUER", "portfolio-api"),
 80 | 		AccessTokenTTL:  getEnvMinutes("JWT_ACCESS_TTL_MINUTES", 15),
 81 | 		RefreshTokenTTL: getEnvDays("JWT_REFRESH_TTL_DAYS", 30),
 82 | 
 83 | 		OTPLength:         getEnvInt("AUTH_OTP_LENGTH", 6),
 84 | 		OTPTTL:            getEnvMinutes("AUTH_OTP_TTL_MINUTES", 10),
 85 | 		OTPMaxAttempts:    getEnvInt("AUTH_OTP_MAX_ATTEMPTS", 5),
 86 | 		OTPMaxPerWindow:   getEnvInt("AUTH_OTP_MAX_PER_WINDOW", 5),
 87 | 		OTPWindow:         getEnvMinutes("AUTH_OTP_WINDOW_MINUTES", 60),
 88 | 		OTPResendCooldown: getEnvSeconds("AUTH_OTP_RESEND_COOLDOWN_SECONDS", 30),
 89 | 		MinPasswordLength: getEnvInt("AUTH_MIN_PASSWORD_LENGTH", 12),
 90 | 		LoginMaxAttempts:  getEnvInt("AUTH_LOGIN_MAX_ATTEMPTS", 10),
 91 | 		LoginWindow:       getEnvMinutes("AUTH_LOGIN_WINDOW_MINUTES", 15),
 92 | 
 93 | 		EmailProvider:       strings.ToLower(getEnv("EMAIL_PROVIDER", EmailProviderSES)),
 94 | 		AWSRegion:           getEnv("AWS_REGION", "ap-south-1"),
 95 | 		AWSAccessKeyID:      os.Getenv("AWS_ACCESS_KEY_ID"),
 96 | 		AWSSecretAccessKey:  os.Getenv("AWS_SECRET_ACCESS_KEY"),
 97 | 		AWSSessionToken:     os.Getenv("AWS_SESSION_TOKEN"),
 98 | 		SESEndpointURL:      os.Getenv("SES_ENDPOINT_URL"),
 99 | 		SESFromEmail:        os.Getenv("SES_FROM_EMAIL"),
100 | 		SESFromName:         getEnv("SES_FROM_NAME", "Portfolio Admin"),
101 | 		SESReplyTo:          os.Getenv("SES_REPLY_TO"),
102 | 		SESConfigurationSet: os.Getenv("SES_CONFIGURATION_SET"),
103 | 	}
104 | 
105 | 	cfg.validate()
106 | 	return cfg
107 | }
108 | 
109 | // validate fails the boot when a required setting is missing or nonsensical.
110 | func (c *Config) validate() {
111 | 	if c.TursoURL == "" || c.TursoToken == "" {
112 | 		log.Fatal("TURSO_DATABASE_URL and TURSO_AUTH_TOKEN must be set")
113 | 	}
114 | 	if len(c.JWTSecret) < 32 {
115 | 		log.Fatal("JWT_SECRET must be set and at least 32 characters long")
116 | 	}
117 | 	if c.EmailProvider != EmailProviderSES && c.EmailProvider != EmailProviderLog {
118 | 		log.Fatalf("EMAIL_PROVIDER must be %q or %q (got %q)", EmailProviderSES, EmailProviderLog, c.EmailProvider)
119 | 	}
120 | 	if c.EmailProvider == EmailProviderSES {
121 | 		if c.SESFromEmail == "" {
122 | 			log.Fatal("SES_FROM_EMAIL must be set when EMAIL_PROVIDER=ses")
123 | 		}
124 | 		if c.AWSRegion == "" {
125 | 			log.Fatal("AWS_REGION must be set when EMAIL_PROVIDER=ses")
126 | 		}
127 | 		if (c.AWSAccessKeyID == "") != (c.AWSSecretAccessKey == "") {
128 | 			log.Fatal("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set together (omit both to use the Lambda IAM role)")
129 | 		}
130 | 	}
131 | 	if c.OTPLength < 4 || c.OTPLength > 10 {
132 | 		log.Fatal("AUTH_OTP_LENGTH must be between 4 and 10")
133 | 	}
134 | 	if c.MinPasswordLength < 8 {
135 | 		log.Fatal("AUTH_MIN_PASSWORD_LENGTH must be at least 8")
136 | 	}
137 | }
