139 | // UsesSES reports whether real mails are sent through AWS SES.
140 | func (c *Config) UsesSES() bool { return c.EmailProvider == EmailProviderSES }
141 | 
142 | // MailFrom renders the RFC 5322 From header, e.g. `Portfolio Admin <no-reply@x.com>`.
143 | func (c *Config) MailFrom() string {
144 | 	if c.SESFromName == "" {
145 | 		return c.SESFromEmail
146 | 	}
147 | 	return c.SESFromName + " <" + c.SESFromEmail + ">"
148 | }
