150 | func getEnv(key, fallback string) string {
151 | 	if v, ok := os.LookupEnv(key); ok && v != "" {
152 | 		return v
153 | 	}
154 | 	return fallback
155 | }
156 | 
157 | func getEnvInt(key string, fallback int) int {
158 | 	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
159 | 		n, err := strconv.Atoi(strings.TrimSpace(v))
160 | 		if err != nil {
161 | 			log.Fatalf("%s must be an integer (got %q)", key, v)
162 | 		}
163 | 		return n
164 | 	}
165 | 	return fallback
166 | }
167 | 
168 | func getEnvMinutes(key string, fallback int) time.Duration {
169 | 	return time.Duration(getEnvInt(key, fallback)) * time.Minute
170 | }
171 | 
172 | func getEnvSeconds(key string, fallback int) time.Duration {
173 | 	return time.Duration(getEnvInt(key, fallback)) * time.Second
174 | }
175 | 
176 | func getEnvDays(key string, fallback int) time.Duration {
177 | 	return time.Duration(getEnvInt(key, fallback)) * 24 * time.Hour
178 | }
179 | 
180 | func getEnvCSV(key string, fallback []string) []string {
181 | 	v, ok := os.LookupEnv(key)
182 | 	if !ok || strings.TrimSpace(v) == "" {
183 | 		return fallback
184 | 	}
185 | 	out := make([]string, 0, len(fallback))
186 | 	for _, p := range strings.Split(v, ",") {
187 | 		if trimmed := strings.TrimSpace(p); trimmed != "" {
188 | 			out = append(out, trimmed)
189 | 		}
190 | 	}
191 | 	if len(out) == 0 {
192 | 		return fallback
193 | 	}
194 | 	return out
195 | }

