 18 | 	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
 19 | 	switch {
 20 | 	case err == nil:
 21 | 		if cfg.IsEnabled {
 22 | 			return cfg, nil
 23 | 		}
