155 | // ResendLoginOTP invalidates the previous code and mails a fresh one, subject
156 | // to the resend cooldown so the endpoint cannot be used to spam the admin.
157 | func (s *AuthService) ResendLoginOTP(ctx context.Context, in ResendOTPInput, meta RequestMeta) (*ChallengeView, error) {
158 | 	challenge, err := s.otps.FindByID(ctx, in.ChallengeID)
159 | 	if err != nil {
160 | 		if errors.Is(err, models.ErrNotFound) {
161 | 			return nil, errInvalidChallenge()
162 | 		}
163 | 		return nil, err
164 | 	}
165 | 	if challenge.Purpose != models.OTPPurposeLogin2FA || challenge.IsConsumed() {
166 | 		return nil, errChallengeUsed()
167 | 	}
168 | 
169 | 	admin, err := s.adminFor(ctx, challenge.AdminID)
170 | 	if err != nil {
171 | 		return nil, err
172 | 	}
173 | 	if !admin.IsActive {
174 | 		return nil, errAccountDisabled()
175 | 	}
176 | 
177 | 	if pending, err := s.otps.FindLatestPending(ctx, admin.ID, models.OTPPurposeLogin2FA, s.now()); err == nil {
178 | 		availableAt := pending.CreatedAt.Add(s.cfg.OTPResendCooldown)
179 | 		if s.now().Before(availableAt) {
180 | 			return nil, errOTPCooldown(int(availableAt.Sub(s.now()).Seconds()) + 1)
181 | 		}
182 | 	} else if !errors.Is(err, models.ErrNotFound) {
183 | 		return nil, err
184 | 	}
185 | 
186 | 	view, err := s.issueOTP(ctx, admin, models.OTPPurposeLogin2FA, meta)
187 | 	if err != nil {
188 | 		return nil, err
189 | 	}
190 | 	s.auditEvent(ctx, admin.ID, models.AuditOTPResent, "email_otp", nil)
191 | 	return view, nil
