 21 | 	OTPs    OTPStore
 22 | 	Refresh RefreshStore
 23 | 	Audit   AuditStore
 24 | 	Mailer  email.Sender
 25 | 	Tokens  *security.TokenManager
 26 | 	Cfg     *config.Config
 27 | 	// Now is injectable for deterministic tests; defaults to time.Now (UTC).
 28 | 	Now func() time.Time
 29 | }
 30 | 
 31 | // AuthService owns every admin authentication flow.
 32 | type AuthService struct {
 33 | 	admins       AdminStore
 34 | 	twoFA        TwoFAStore
 35 | 	otps         OTPStore
 36 | 	refresh      RefreshStore
 37 | 	audit        AuditStore
 38 | 	mailer       email.Sender
 39 | 	tokens       *security.TokenManager
 40 | 	cfg          *config.Config
 41 | 	now          func() time.Time
 42 | 	loginLimiter *security.Limiter
 43 | }
 44 | 
 45 | // NewAuthService builds the service.
 46 | func NewAuthService(deps Deps) *AuthService {
 47 | 	now := deps.Now
 48 | 	if now == nil {
 49 | 		now = func() time.Time { return time.Now().UTC() }
 50 | 	}
 51 | 	return &AuthService{
 52 | 		admins:       deps.Admins,
 53 | 		twoFA:        deps.TwoFA,
 54 | 		otps:         deps.OTPs,
 55 | 		refresh:      deps.Refresh,
 56 | 		audit:        deps.Audit,
 57 | 		mailer:       deps.Mailer,
 58 | 		tokens:       deps.Tokens,
 59 | 		cfg:          deps.Cfg,
 60 | 		now:          now,
 61 | 		loginLimiter: security.NewLimiter(deps.Cfg.LoginMaxAttempts, deps.Cfg.LoginWindow),
 62 | 	}
 63 | }
 64 | 
 65 | // Login validates the password, ensures mandatory email OTP is active, mails a
 66 | // code, and returns the challenge that must be completed before a session is
 67 | // issued.
 68 | func (s *AuthService) Login(ctx context.Context, in LoginInput, meta RequestMeta) (*LoginResult, error) {
 69 | 	identifier := strings.TrimSpace(in.Identifier)
 70 | 	if identifier == "" || in.Password == "" {
 71 | 		return nil, errInvalidCredentials()
 72 | 	}
 73 | 
 74 | 	limitKey := security.ClientKey(identifier, meta.IPAddress)
 75 | 	if !s.loginLimiter.Allow(limitKey) {
 76 | 		s.auditEvent(ctx, "", models.AuditRateLimited, "login", map[string]any{"identifier": identifier})
 77 | 		return nil, errRateLimited(int(s.loginLimiter.RetryAfter(limitKey).Seconds()) + 1)
 78 | 	}
 79 | 
 80 | 	admin, err := s.admins.FindByIdentifier(ctx, identifier)
 81 | 	if err != nil {
 82 | 		if errors.Is(err, models.ErrNotFound) {
 83 | 			// Burn the same CPU as a real verification so the response time
 84 | 			// does not disclose whether the account exists.
 85 | 			_, _ = security.VerifyPassword(security.DummyPasswordHash, in.Password)
 86 | 			s.loginLimiter.RegisterFailure(limitKey)
 87 | 			s.auditEvent(ctx, "", models.AuditLoginFailed, "unknown_identifier", map[string]any{"identifier": identifier})
 88 | 			return nil, errInvalidCredentials()
 89 | 		}
 90 | 		return nil, err
 91 | 	}
 92 | 
 93 | 	if !admin.IsActive {
 94 | 		s.loginLimiter.RegisterFailure(limitKey)
 95 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "inactive", nil)
 96 | 		return nil, errAccountDisabled()
 97 | 	}
 98 | 
 99 | 	ok, err := security.VerifyPassword(admin.PasswordHash, in.Password)
100 | 	if err != nil {
101 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
102 | 	}
103 | 	if !ok {
104 | 		s.loginLimiter.RegisterFailure(limitKey)
105 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "bad_password", nil)
106 | 		return nil, errInvalidCredentials()
107 | 	}
108 | 	s.loginLimiter.Reset(limitKey)
109 | 
110 | 	// Opportunistically upgrade hashes produced with weaker parameters.
111 | 	if security.NeedsRehash(admin.PasswordHash) {
112 | 		if hash, err := security.HashPassword(in.Password); err == nil {
113 | 			if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
114 | 				log.Printf("⚠️  auth: password rehash failed for admin %s: %v", admin.ID, err)
115 | 			}
116 | 		}
117 | 	}
118 | 
119 | 	if _, err := s.emailTwoFAConfig(ctx, admin); err != nil {
120 | 		return nil, err
121 | 	}
122 | 
123 | 	challenge, err := s.issueOTP(ctx, admin, models.OTPPurposeLogin2FA, meta)
124 | 	if err != nil {
125 | 		return nil, err
126 | 	}
127 | 	s.auditEvent(ctx, admin.ID, models.AuditLoginChallenged, "email_otp", nil)
128 | 	return &LoginResult{TwoFactorRequired: true, Challenge: challenge}, nil
129 | }
130 | 
131 | // VerifyLoginOTP completes the second factor and starts a session.
132 | func (s *AuthService) VerifyLoginOTP(ctx context.Context, in VerifyOTPInput, meta RequestMeta) (*LoginResult, error) {
133 | 	challenge, err := s.loadChallenge(ctx, in.ChallengeID, models.OTPPurposeLogin2FA)
134 | 	if err != nil {
135 | 		return nil, err
136 | 	}
137 | 
138 | 	admin, err := s.checkOTP(ctx, challenge, in.OTP)
139 | 	if err != nil {
140 | 		return nil, err
141 | 	}
142 | 
143 | 	if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
144 | 		log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
145 | 	}
146 | 
147 | 	tokens, err := s.issueSession(ctx, admin, meta)
148 | 	if err != nil {
149 | 		return nil, err
150 | 	}
151 | 	s.auditEvent(ctx, admin.ID, models.AuditLoginSucceeded, "email_otp", nil)
152 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
153 | }
154 | 
155 | // ResendLoginOTP invalidates the previous code and mails a fresh one, subject
156 | // to the resend cooldown so the endpoint cannot be used to spam the admin.
157 | func (s *AuthService) ResendLoginOTP(ctx context.Context, in ResendOTPInput, meta RequestMeta) (*ChallengeView, error) {
158 | 	challenge, err := s.otps.FindByID(ctx, in.ChallengeID)
159 | 	if err != nil {
160 | 		if errors.Is(err, models.ErrNotFound) {
161 | 			return nil, errInvalidChallenge()
162 | 		}
163 | 		return nil, err
164 | 	}
165 | 	if challenge.Purpose != models.OTPPurposeLogin2FA || challenge.IsConsumed() {
166 | 		return nil, errChallengeUsed()
167 | 	}
168 | 
169 | 	admin, err := s.adminFor(ctx, challenge.AdminID)
170 | 	if err != nil {
171 | 		return nil, err
172 | 	}
173 | 	if !admin.IsActive {
174 | 		return nil, errAccountDisabled()
175 | 	}
176 | 
177 | 	if pending, err := s.otps.FindLatestPending(ctx, admin.ID, models.OTPPurposeLogin2FA, s.now()); err == nil {
178 | 		availableAt := pending.CreatedAt.Add(s.cfg.OTPResendCooldown)
179 | 		if s.now().Before(availableAt) {
180 | 			return nil, errOTPCooldown(int(availableAt.Sub(s.now()).Seconds()) + 1)
181 | 		}
182 | 	} else if !errors.Is(err, models.ErrNotFound) {
183 | 		return nil, err
184 | 	}
185 | 
186 | 	view, err := s.issueOTP(ctx, admin, models.OTPPurposeLogin2FA, meta)
187 | 	if err != nil {
188 | 		return nil, err
189 | 	}
190 | 	s.auditEvent(ctx, admin.ID, models.AuditOTPResent, "email_otp", nil)
191 | 	return view, nil
192 | }

 1 | // Package apierr defines the single error type the service layer returns and
 2 | // the HTTP layer understands. Using one type keeps the mapping from business
 3 | // failure to status code + machine-readable code in exactly one place.
 4 | package apierr
 5 | 
 6 | import (
 7 | 	"errors"
 8 | 	"fmt"
 9 | 	"net/http"
10 | )
11 | 
12 | // Error is an API-visible error: an HTTP status, a stable machine-readable
13 | // code the frontend can switch on, and a human message.
14 | type Error struct {
15 | 	Status  int
16 | 	Code    string
17 | 	Message string
18 | 	Err     error
19 | 	// RetryAfter (seconds) is emitted as the Retry-After header when > 0.
20 | 	RetryAfter int
21 | }
22 | 
23 | func (e *Error) Error() string {
24 | 	if e.Err != nil {
25 | 		return fmt.Sprintf("%s: %s: %v", e.Code, e.Message, e.Err)
26 | 	}
27 | 	return fmt.Sprintf("%s: %s", e.Code, e.Message)
28 | }
29 | 
30 | func (e *Error) Unwrap() error { return e.Err }
31 | 
32 | // New builds an error without an underlying cause.
33 | func New(status int, code, message string) *Error {
34 | 	return &Error{Status: status, Code: code, Message: message}
35 | }
36 | 
37 | // Wrap builds an error that keeps the cause for logs while exposing only the
38 | // curated message to clients.
39 | func Wrap(err error, status int, code, message string) *Error {
40 | 	return &Error{Status: status, Code: code, Message: message, Err: err}
41 | }
42 | 
43 | // From extracts the API error from err, or returns nil when err is nil.
44 | // Non-API errors become a generic 500 so internal details never leak.
45 | func From(err error) *Error {
46 | 	if err == nil {
47 | 		return nil
48 | 	}
49 | 	var apiErr *Error
50 | 	if errors.As(err, &apiErr) {
51 | 		return apiErr
52 | 	}
53 | 	return Wrap(err, http.StatusInternalServerError, "internal_error", "Something went wrong. Please try again.")
54 | }
55 | 
56 | // BadRequest is a helper for handler-level payload validation.
57 | func BadRequest(code, message string) *Error {
58 | 	return New(http.StatusBadRequest, code, message)
59 | }
60 | 
61 | // Unauthorized is a helper for missing/invalid credentials.
62 | func Unauthorized(code, message string) *Error {
63 | 	return New(http.StatusUnauthorized, code, message)
64 | }

