 3 | import (
 4 | 	"database/sql"
 5 | 	"strings"
 6 | 	"time"
 7 | )
 8 | 
 9 | // SQLiteTimeLayout is the text format SQLite's datetime('now') produces —
10 | // which is what every DEFAULT in db_schema.sql uses. All timestamps written
11 | // by the API use the same fixed-width UTC layout so that lexicographic
12 | // string comparison in SQL is also chronological comparison.
13 | const SQLiteTimeLayout = "2006-01-02 15:04:05"
14 | 
15 | // FormatTime renders t as a UTC SQLite datetime string.
16 | func FormatTime(t time.Time) string {
17 | 	return t.UTC().Format(SQLiteTimeLayout)
18 | }
19 | 
20 | // FormatTimePtr renders a nullable timestamp as a driver argument
21 | // (string or nil).
22 | func FormatTimePtr(t *time.Time) any {
23 | 	if t == nil {
24 | 		return nil
25 | 	}
26 | 	return FormatTime(*t)
27 | }
28 | 
29 | // ParseTime parses a SQLite datetime string, tolerating the "T" separator,
30 | // fractional seconds and a trailing "Z" so values written by other tools work.
31 | func ParseTime(s string) (time.Time, error) {
32 | 	trimmed := strings.TrimSuffix(strings.TrimSpace(s), "Z")
33 | 	layouts := []string{
34 | 		SQLiteTimeLayout + ".999999999",
35 | 		"2006-01-02T15:04:05.999999999",
36 | 		SQLiteTimeLayout,
37 | 		"2006-01-02T15:04:05",
38 | 		"2006-01-02",
39 | 	}
40 | 	var err error
41 | 	for _, layout := range layouts {
42 | 		var t time.Time
43 | 		t, err = time.ParseInLocation(layout, trimmed, time.UTC)
44 | 		if err == nil {
45 | 			return t.UTC(), nil
46 | 		}
47 | 	}
48 | 	return time.Time{}, err
49 | }
50 | 
51 | // ParseTimePtr parses a nullable datetime column into a *time.Time.
52 | func ParseTimePtr(v sql.NullString) (*time.Time, error) {
53 | 	if !v.Valid || strings.TrimSpace(v.String) == "" {
54 | 		return nil, nil
55 | 	}
56 | 	t, err := ParseTime(v.String)
57 | 	if err != nil {
58 | 		return nil, err
59 | 	}
60 | 	return &t, nil
61 | }
62 | 
63 | // ParseTimeValue parses a required datetime column.
64 | func ParseTimeValue(v string) (time.Time, error) {
65 | 	return ParseTime(v)
66 | }

