		GithubURL:       body.GithubURL,
		PortfolioURL:    body.PortfolioURL,
		TwitterURL:      body.TwitterURL,
		ResumeFileURL:   body.ResumeFileURL,
		CareerGapNote:   body.CareerGapNote,
		ExperienceLevel: body.ExperienceLevel,
